$before=@(Get-CimInstance Win32_Process -Filter "Name='WINWORD.EXE'"|Select-Object -ExpandProperty ProcessId|Sort-Object);$word=$null;$doc=$null;$newPid=$null;$started=(Get-Date).ToString('o')
