xtendedProperty('Number of Pages');new_word_pid=$newPid;new_word_pid_exited=$exited;preexisting_word_pids_unchanged=$baseline;preexisting_count=$before.Count;unexpected_new_word_pids=$unexpected;started_at=$started;verified_at=(Get-Date).ToString('o');error=$null}}
catch{$err=$_.Exception.Message;Phase ('ERROR '+$err+' '+$_.ScriptStackTrace);$res=[pscustomobject]@{status='FAIL';doc_id='0105';revision='R04';source_docx_path=$docx;pdf_path=$pdf;new_word_pid=$newPid;preexisting_word_pids=$before;started_at=$started;verified_at=(Get-Date).ToString('o');error=$err;error_stack=$_.ScriptStackTrace};if($newPid -and $word){try{if($doc){$doc.Close(0);[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($doc)}}catch{};try{$word.Quit(0);[void][Runtime.InteropServices.Marshal]::FinalReleaseComObject($word)}catch{}}}
$res|ConvertTo-Json -Depth 5|Set-Content -LiteralPath (Join-Path $base 'evidence\word_export_range_receipt_R04.json') -Encoding UTF8;$res|ConvertTo-Json -Depth 5;if($res.status -ne 'PASS'){exit 1}